@page "/apply"
@using sv_d27985555c41446cb411f83c687664fc.Components.JobApplication
@using sv_d27985555c41446cb411f83c687664fc.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@currentStep"
                   StepNames="@stepNames"
                   CompletedSteps="@completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@fullName"
                              Email="@email"
                              Phone="@phone"
                              Address="@address"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalInfoNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep References="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep FullName="@fullName"
                        Email="@email"
                        Phone="@phone"
                        Address="@address"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        IsSubmitting="@isSubmitting"
                        IsSubmitted="@isSubmitted"
                        ApplicationId="@applicationId"
                        ErrorMessage="@submitError"
                        OnEdit="GoToStep"
                        OnBack="GoBack"
                        OnSubmit="HandleSubmit" />
            break;
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();
    private static readonly IReadOnlyList<string> stepNames = new[] { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    // Step 1 state
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 state
    private List<WorkEntryForm.WorkEntryModel> workEntries = new();

    // Step 3 state
    private List<ReferenceForm.ReferenceModel> references = new();

    // Step 4 state
    private string coverLetter = "";

    // Submission state
    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? submitError;

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        fullName = result.FullName;
        email = result.Email;
        phone = result.Phone;
        address = result.Address;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntryForm.WorkEntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceForm.ReferenceModel> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;
        StateHasChanged();

        try
        {
            var app = new JobApplication(
                new PersonalInfo(fullName, email, phone, address),
                new WorkHistory(workEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
                references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                coverLetter
            );

            applicationId = await ApplicationService.SubmitApplicationAsync(app);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private void GoToStep(int step)
    {
        if (completedSteps.Contains(step) || step == currentStep)
            currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }
}

